using System.Collections;
using LittleLeo;
using UnityEngine;

namespace Astrea.BattleActions;

[CreateAssetMenu(fileName = "FieryProjectionAction", menuName = "Data/Battle/Battle Actions/Sothis/FieryProjection Action")]
public class FieryProjectionAction : PurifyEffectAmountAction
{
	[Header("Soul Heat")]
	[SerializeField]
	private SoulHeat soulHeat;

	[Header("VFX Animation")]
	[SerializeField]
	private AnimationCurve fireTrailAnimationCurve;

	[SerializeField]
	private AnimationCurve fireTrailAnimationHeightCurve;

	[SerializeField]
	private float fireTrailAnimationHeight;

	public override int PurifyCounter(bool checkConditionToBeCastedOrPreview)
	{
		return soulHeat.SoulHeatCounter * Mathf.CeilToInt((float)base.PurifyCounter(checkConditionToBeCastedOrPreview) / 2f);
	}

	public override void CastTarget(GameObject target, GameObject source)
	{
		if (ReferenceSingleton<VFXHandler>.Instance.IsVFXEnabled())
		{
			ReferenceSingleton<GameStateManager>.Instance.ActionsQueueState.EnqueueAction(CastTargetAmountVFXDelay(target, 0, source));
			ReferenceSingleton<GameStateManager>.Instance.SetActionsQueueState();
		}
		else
		{
			BeforePurify(source);
			DefaultSingleTargetCast(target, 0, source);
		}
	}

	private IEnumerator CastTargetAmountVFXDelay(GameObject target, int amount, GameObject source)
	{
		BeforePurify(source);
		PlaySFX();
		GameObject trailVFX = GetVFX(GetVFXOwnerPosition(source));
		ParticleEmissionController particleEmissionController = trailVFX.GetComponent<ParticleEmissionController>();
		particleEmissionController.SetActive(value: true);
		Vector3 startPosition = trailVFX.transform.position;
		Vector3 targetPosition = GetVFXOwnerPosition(target);
		yield return ReferenceSingleton<CoroutineHandler>.Instance.StartCoroutine(CoroutineUtility.CurveRoutine(vfxDelay, fireTrailAnimationCurve, delegate(float t, float v)
		{
			trailVFX.transform.position = Vector3.Lerp(startPosition, targetPosition, v) + Vector3.up * fireTrailAnimationHeight * fireTrailAnimationHeightCurve.Evaluate(t);
		}));
		particleEmissionController.SetActive(value: false);
		ReferenceSingleton<PoolHandler>.Instance.StoreObject(trailVFX, 3f);
		SpawnSecondVFX(GetVFXOwnerPosition(target), 3f);
		DefaultSingleTargetCast(target, amount, source);
	}

	private void DefaultSingleTargetCast(GameObject target, int amount, GameObject source)
	{
		purifyCorruptAction.CastTargetAmount(target, PurifyAmount(amount), source);
		CheckCancelAutoOnDiceCastedOnRuneCasted(source);
		AfterPurify(source);
	}
}
